import {
  Bars3BottomLeftIcon,
  CircleStackIcon,
  CloudIcon,
  CodeBracketIcon,
  FolderIcon
} from '@heroicons/react/24/outline';
import { useSelector } from 'react-redux';
import { selectConfig, selectInfo, selectReadonly } from '~/app/meta/metaSlice';
import { StorageType } from '~/types/Meta';
import { useSession } from '~/data/hooks/session';
import Notifications from './header/Notifications';
import UserProfile from './header/UserProfile';

type HeaderProps = {
  setSidebarOpen: (sidebarOpen: boolean) => void;
};

export default function Header(props: HeaderProps) {
  const { setSidebarOpen } = props;

  const info = useSelector(selectInfo);
  const readOnly = useSelector(selectReadonly);
  const config = useSelector(selectConfig);

  const storageIcon = {
    [StorageType.DATABASE]: <CircleStackIcon className="h-5 w-5" aria-hidden="true" />,
    [StorageType.LOCAL]: <FolderIcon className="h-5 w-5" aria-hidden="true" />,
    [StorageType.GIT]: <CodeBracketIcon className="h-5 w-5" aria-hidden="true" />,
    [StorageType.OBJECT]: <CloudIcon className="h-5 w-5" aria-hidden="true" />
  }[config.storage.type];

  const { session } = useSession();

  return (
    <div className="bg-violet-400 sticky top-0 z-10 flex h-16 flex-shrink-0">
      <button
        type="button"
        className="without-ring text-white px-4 md:hidden"
        onClick={() => setSidebarOpen(true)}
      >
        <span className="sr-only">Open sidebar</span>
        <Bars3BottomLeftIcon className="h-6 w-6" aria-hidden="true" />
      </button>

      <div className="flex flex-1 justify-between px-4">
        <div className="flex flex-1" />
        <div className="ml-4 flex items-center space-x-1.5 md:ml-6">
          <span
            className="text-white"
            role="img"
            aria-label={`${config.storage.type} storage`}
            title={`${config.storage.type} storage`}
          >
            {storageIcon}
          </span>
          {/* read-only mode */}
          {readOnly && (
            <span className="nightwind-prevent bg-violet-200 inline-flex items-center gap-x-1.5 rounded-full px-3 py-1 text-xs font-medium text-violet-950">
              <svg
                className="h-1.5 w-1.5 fill-orange-400"
                viewBox="0 0 6 6"
                aria-hidden="true"
              >
                <circle cx={3} cy={3} r={3} />
              </svg>
              Read-Only
            </span>
          )}
          {/* notifications */}
          {info && info.updateAvailable && <Notifications info={info} />}

          {/* user profile */}
          {session && session.self && (
            <UserProfile
              name={session.self.metadata['io.flipt.auth.oidc.name']}
              imgURL={session.self.metadata['io.flipt.auth.oidc.picture']}
            />
          )}
        </div>
      </div>
    </div>
  );
}
